gKf(){return"\u0639\u0646\u062f\u0645\u0627 \u062a\u0628\u062f\u0648 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0645\u0631\u064a\u0628\u0629\u060c \u064a\u0645\u0643\u0646 \u0644\u0645\u0646 \u062a\u062b\u0642 \u0628\u0647\u0645 \u0645\u0633\u0627\u0639\u062f\u062a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0642\u0631\u0627\u0631. \u062a\u062d\u0635\u0644 \u0643\u0644 \u0646\u0633\u062e\u0629 \u0645\u0646 VoxGuard \u0639\u0644\u0649 \u0645\u0639\u0631\u0641 Family Shield \u0645\u064f\u0628\u0647\u0645 \u2014 \u064a\u062d\u0641\u0638\u0647 \u0627\u0644\u0645\u0642\u0631\u0628\u0648\u0646 \u0641\u064a \u062f\u0627\u0626\u0631\u062a\u0647\u0645 \u0627\u0644\u0645\u0648\u062b\u0648\u0642\u0629 \u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u062a\u0646\u0628\u064a\u0647\u0627\u062a \u0627\u0644\u0623\u0645\u0627\u0646 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0643 \u0648\u0627\u0644\u0631\u062f \u0639\u0644\u064a\u0647\u0627."},
gKq(){return"\u062a\u064f\u0639\u0627\u0644\u064e\u062c \u0623\u0635\u0648\u0627\u062a \u0627\u0644\u0645\u064a\u0643\u0631\u0648\u0641\u0648\u0646 \u0641\u064a \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062c\u0644\u0633\u0629 \u2014 \u0644\u0627 \u064a\u062e\u0632\u0651\u0646 VoxGuard \u0623\u064a \u062a\u0633\u062c\u064a\u0644 \u0635\u0648\u062a\u064a \u0623\u0628\u062f\u064b\u0627. \u064a\u0637\u0644\u0628 Live Mic \u0625\u0630\u0646 \u0627\u0644\u0645\u064a\u0643\u0631\u0648\u0641\u0648\u0646 \u0641\u0642\u0637 \u0639\u0646\u062f\u0645\u0627 \u062a\u062e\u062a\u0627\u0631\u0647\u061b \u0648\u064a\u0639\u0645\u0644 \u0648\u0636\u0639 \u0627\u0644\u0639\u0631\u0636 \u0628\u062f\u0648\u0646\u0647."},
gKm(){return"\u062a\u062d\u0645\u0644 \u062a\u0646\u0628\u064a\u0647\u0627\u062a Family Shield \u0641\u0642\u0637 \u0645\u0639\u0631\u0641 VoxGuard \u0645\u064f\u0628\u0647\u0645\u064b\u0627 \u0648\u0645\u0631\u062c\u0639 \u062d\u0627\u062f\u062b\u0629 \u0648\u0645\u0633\u062a\u0648\u0649 \u062e\u0637\u0631 \u2014 \u0644\u0627 \u0635\u0648\u062a \u0648\u0644\u0627 \u0646\u0635\u0648\u0635\u064b\u0627 \u0648\u0644\u0627 \u0623\u0633\u0645\u0627\u0621 \u0648\u0644\u0627 \u0623\u0631\u0642\u0627\u0645 \u0647\u0648\u0627\u062a\u0641 \u0623\u0628\u062f\u064b\u0627."},
gNG(){return"\u0644\u0645\u0627\u0630\u0627 \u0623\u0634\u0627\u0631 VoxGuard \u0625\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629"},
gNC(){return"\u0644\u0645\u0627\u0630\u0627 \u0631\u0635\u062f VoxGuard \u0625\u0634\u0627\u0631\u0627\u062a \u0635\u0648\u062a\u064a\u0629 \u0645\u0631\u062a\u0641\u0639\u0629"},
gNF(){return"\u0644\u0645\u0627\u0630\u0627 \u0623\u0634\u0627\u0631 VoxGuard \u0625\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062a\u0633\u062c\u064a\u0644"},
gND(){return"\u0644\u0645\u0627\u0630\u0627 \u0623\u0634\u0627\u0631 VoxGuard \u0625\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629"},
gNE(){return"\u0644\u0645\u0627\u0630\u0627 \u0623\u0634\u0627\u0631 VoxGuard \u0625\u0644\u064a\u0647\u0627"},
gNB(){return"\u0637\u0631\u064a\u0642\u0629 \u0623\u0647\u062f\u0623 \u0644\u0644\u0631\u062f."},
gNA(){return"\u064a\u0633\u0627\u0639\u062f\u0643 VoxGuard \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0642\u0641 \u0648\u0627\u0644\u062a\u062d\u0642\u0642 \u0648\u0627\u0644\u0628\u0642\u0627\u0621 \u0645\u0633\u064a\u0637\u0631\u064b\u0627 \u0639\u0646\u062f\u0645\u0627 \u062a\u0628\u062f\u0648 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0645\u0631\u064a\u0628\u0629."},
gNv(){return"\u0627\u062e\u062a\u0631 \u0644\u063a\u062a\u0643"},
