gNz(){return"\u0628\u0645\u0627\u0630\u0627 \u0646\u0646\u0627\u062f\u064a\u0643\u061f"},
gNx(){return"\u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0623\u0648\u0644 \u0623\u0648 \u0627\u0633\u0645 \u0627\u0644\u062f\u0644\u0639"},
gNy(){return"\u0627\u062e\u062a\u064a\u0627\u0631\u064a \u2014 \u064a\u064f\u062d\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u0641\u0642\u0637."},
gNu(){return"\u0645\u062a\u0627\u0628\u0639\u0629"},
gKH(){return"\u0627\u0644\u0635\u0648\u062a \u0627\u0644\u0645\u0623\u0644\u0648\u0641 \u0642\u062f \u064a\u0643\u0648\u0646 \u0645\u0636\u0644\u0644\u064b\u0627 \u0623\u064a\u0636\u064b\u0627."},
gKE(){return"\u064a\u0633\u062a\u0646\u0633\u062e \u0627\u0644\u0645\u062d\u062a\u0627\u0644\u0648\u0646 \u0627\u0644\u0623\u0635\u0648\u0627\u062a \u0648\u064a\u0632\u0648\u0651\u0631\u0648\u0646 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0648\u064a\u0636\u063a\u0637\u0648\u0646 \u0639\u0644\u0649 \u0645\u0646 \u062a\u062d\u0628. \u0633\u0645\u0627\u0639 \u0635\u0648\u062a \u0645\u0623\u0644\u0648\u0641 \u0644\u064a\u0633 \u062f\u0644\u064a\u0644\u064b\u0627 \u0639\u0644\u0649 \u0647\u0648\u064a\u0629 \u0627\u0644\u0645\u062a\u062d\u062f\u062b."},
gKF(){return"\u0627\u0644\u0627\u0633\u062a\u0639\u062c\u0627\u0644 \u0648\u0627\u0644\u0633\u0631\u064a\u0629 \u0648\u0636\u063a\u0637 \u0627\u0644\u062f\u0641\u0639 \u0647\u064a \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629 \u2014 \u0648\u0644\u064a\u0633 \u0627\u0644\u0635\u0648\u062a \u0646\u0641\u0633\u0647."},
gKG(){return"\u0645\u0639\u0631\u0641 \u0627\u0644\u0645\u062a\u0635\u0644 \u0648\u0627\u0644\u0635\u0648\u062a \u0648\u062d\u062f\u0647\u0645\u0627 \u0644\u0627 \u064a\u0645\u0643\u0646\u0647\u0645\u0627 \u0625\u062b\u0628\u0627\u062a \u0627\u0644\u0647\u0648\u064a\u0629 \u0623\u0628\u062f\u064b\u0627."},
gKy(){return"\u0625\u0634\u0627\u0631\u062a\u0627\u0646. \u0642\u0631\u0627\u0631 \u0628\u0634\u0631\u064a \u0648\u0627\u062d\u062f."},
gKw(){return"\u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u2014 \u0627\u0644\u0627\u0633\u062a\u0639\u062c\u0627\u0644 \u0648\u0645\u0637\u0627\u0644\u0628 \u0627\u0644\u062f\u0641\u0639 \u0648\u0636\u063a\u0637 \u0627\u0644\u0633\u0631\u064a\u0629 \u0641\u064a\u0645\u0627 \u064a\u064f\u0642\u0627\u0644."},
gKu(){return"\u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u0635\u0648\u062a \u2014 \u0645\u0624\u0634\u0631\u0627\u062a \u0634\u0630\u0648\u0630\u061b \u0623\u0633\u0644\u0648\u0628 \u0645\u0633\u0627\u0639\u062f \u062a\u0642\u062f\u064a\u0631\u064a \u0648\u0644\u064a\u0633 \u062d\u0643\u0645\u064b\u0627 \u062c\u0646\u0627\u0626\u064a\u064b\u0627."},
gKv(){return"\u062f\u0631\u062c\u0629 \u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u062e\u0637\u0631 \u0647\u064a \u0625\u0634\u0627\u0631\u0629\u060c \u0648\u0644\u064a\u0633\u062a \u0627\u062d\u062a\u0645\u0627\u0644 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0645\u0632\u064a\u0641\u0629."},
gKD(){return"\u0639\u0646\u062f\u0645\u0627 \u062a\u0634\u0639\u0631 \u0623\u0646 \u0634\u064a\u0626\u064b\u0627 \u0645\u0627 \u062e\u0627\u0637\u0626\u060c \u062a\u062d\u0642\u0642 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u0644."},
gKz(){return"\u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u062e\u0637\u0631 \u0633\u0628\u0628 \u0644\u0644\u062a\u0648\u0642\u0641 \u2014 \u0648\u0644\u064a\u0633\u062a \u062d\u0643\u0645\u064b\u0627. \u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u0623\u0642\u0648\u0649 \u062f\u0627\u0626\u0645\u064b\u0627 \u0628\u064a\u062f\u0643:"},
gKA(){return"\u062a\u0648\u0642\u0641 \u2014 \u0644\u0627 \u062a\u0631\u0633\u0644 \u0623\u0645\u0648\u0627\u0644\u064b\u0627 \u0623\u0648 \u0631\u0645\u0648\u0632\u064b\u0627 \u0623\u0648 \u0628\u064a\u0627\u0646\u0627\u062a \u062a\u062d\u062a \u0627\u0644\u0636\u063a\u0637 \u0623\u0628\u062f\u064b\u0627."},
gKB(){return"\u0623\u0639\u062f \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0634\u062e\u0635 \u0639\u0644\u0649 \u0631\u0642\u0645 \u062a\u062b\u0642 \u0628\u0647 \u0645\u0633\u0628\u0642\u064b\u0627 \u2014 \u0648\u0644\u064a\u0633 \u0631\u0642\u0645\u064b\u0627 \u0623\u0639\u0637\u0627\u0643 \u0625\u064a\u0627\u0647 \u0627\u0644\u0645\u062a\u0635\u0644."},
gKC(){return"\u0627\u062a\u0641\u0642 \u0639\u0644\u0649 \u0639\u0628\u0627\u0631\u0629 \u0623\u0645\u0627\u0646 \u0639\u0627\u0626\u0644\u064a\u0629 \u062f\u0648\u0646 \u0627\u062a\u0635\u0627\u0644 \u2014 \u0627\u0637\u0644\u0628\u0647\u0627 \u0639\u0646\u062f\u0645\u0627 \u062a\u0628\u062f\u0648 \u0627\u0644\u0645\u0643\u0627\u0644\u0645\u0629 \u0645\u0631\u064a\u0628\u0629."},
gKj(){return"Family Shield: \u0639\u064a\u0648\u0646 \u0625\u0636\u0627\u0641\u064a\u0629 \u062a\u0633\u0646\u062f\u0643."},
gKg(){return"\u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0648\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0647\u0648\u0627\u062a\u0641 \u0627\u0644\u0645\u0648\u062b\u0648\u0642\u0629 \u062a\u0628\u0642\u0649 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u0630\u064a \u062d\u0641\u0638\u0647\u0627."},
gKh(){return"\u0625\u0639\u062f\u0627\u062f \u062f\u0627\u0626\u0631\u062a\u0643 \u0627\u0644\u0645\u0648\u062b\u0648\u0642\u0629 \u0627\u062e\u062a\u064a\u0627\u0631\u064a \u2014 \u064a\u0645\u0643\u0646\u0643 \u0641\u0639\u0644\u0647 \u0644\u0627\u062d\u0642\u064b\u0627 \u0645\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a."},
gKi(){return"\u064a\u0638\u0647\u0631 \u0645\u0639\u0631\u0641 Family Shield \u0647\u0646\u0627 \u0641\u0648\u0631 \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f."},
KI(a){return"\u0645\u0639\u0631\u0641\u0643: "+a},
gy3(){return"\u062a\u0645 \u0646\u0633\u062e \u0645\u0639\u0631\u0651\u0641 Family Shield"},
